with Base as (select * from subscriptions where customer_id in (2, 11, 13, 30) and status in ('CANCELLED', 'ACTIVE', 'PAUSED')), agg as (select month(start_date) as start_month, year(start_date) as start_year, round((100 * sum(case when status = 'ACTIVE' then 1 else 0 end)) / count(*), 1) as pct_active, concat_ws(', ', sort_array(collect_set(status))) as status_values from Base group by month(start_date), year(start_date)) select start_month, start_year, pct_active, status_values from agg order by start_month desc;
